css:
button {
  height: 50px;
  margin: 5px;
  width: 120px;
  cursor: pointer;
  background: #7C4DFF;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: center;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  font-family: Consolas, Courier New, monospace;
  border: solid #754CFF 1px;
  font-size: 16px;
  color: rgb(161, 161, 161);
  -webkit-transition: 500ms;
  transition: 500ms;
  border-radius: 5px;
  background: linear-gradient(145deg, #4A2A99, #360E6F);
  -webkit-box-shadow: -1px -5px 15px #471C8B, 
               5px  5px 15px #471C8B, 
    inset      5px  5px 10px #360E6F, 
    inset     -5px -5px 10px #360E6F;
  box-shadow: -1px -5px 15px #471C8B, 
               5px  5px 15px #471C8B, 
    inset      5px  5px 10px #360E6F, 
    inset     -5px -5px 10px #360E6F;
}

button:hover {
  -webkit-box-shadow: 1px 1px 13px #300A67,
                    -1px -1px 13px #4A2A99;
  box-shadow: 1px 1px 13px #300A67,
             -1px -1px 13px #4A2A99;
  color: #d6d6d6;
  -webkit-transition: 500ms;
  transition: 500ms;
}

button:active {
  -webkit-box-shadow: 1px 1px 13px #300A67,
                     -1px -1px 33px #4A2A99;
  box-shadow: 1px 1px 13px #300A67,
             -1px -1px 33px #4A2A99;
  color: #d6d6d6;
  -webkit-transition: 100ms;
  transition: 100ms;
}
